import{_ as o,o as t,c,ag as r}from"./chunks/framework.B_zcDAFh.js";const h=JSON.parse('{"title":"Cross-Project Sync","description":"","frontmatter":{},"headers":[],"relativePath":"guide/cross-project-sync.md","filePath":"guide/cross-project-sync.md"}'),s={name:"guide/cross-project-sync.md"};function i(a,e,p,d,n,l){return t(),c("div",null,[...e[0]||(e[0]=[r('<h1 id="cross-project-sync" tabindex="-1">Cross-Project Sync <a class="header-anchor" href="#cross-project-sync" aria-label="Permalink to &quot;Cross-Project Sync&quot;">​</a></h1><p>Because the three render-pipeline variants share one set of source files, the repo root holds six <code>.bat</code> scripts (using <code>robocopy /E</code>) that propagate edits between them. Edit code in <code>Boing Kit/Assets/Boing Kit/{Script,Editor,Shader}/</code> — the built-in project is the canonical source — then run the appropriate push script before committing.</p><p>The available scripts are:</p><ul><li><code>boing-kit-push-srp-scripts.bat</code> — copy <code>Script/</code>, <code>Editor/</code>, <code>Shader/</code> from built-in → URP and HDRP.</li><li><code>boing-kit-pull-hdrp-scripts.bat</code> / <code>boing-kit-pull-urp-scripts.bat</code> — pull the same folders back into built-in when an SRP-only fix was made first.</li><li><code>boing-kit-push-srp-examples.bat</code> — copy <code>Examples/</code> from built-in → URP and HDRP.</li><li><code>boing-kit-pull-hdrp-examples.bat</code> / <code>boing-kit-pull-urp-examples.bat</code> — pull <code>Examples/</code> back from a render-pipeline project to built-in.</li></ul><p>Render-pipeline-specific divergence (shader subgraphs, HDRP/URP-only example assets) lives only under <code>Examples/</code> per project, never under <code>Script/Editor/Shader/</code>.</p>',5)])])}const b=o(s,[["render",i]]);export{h as __pageData,b as default};
